import { createTestContext, FluentXmlFluentTest, XmlFluentXmlTest } from '../test-utils'
import { readFileSync } from 'fs'
import { path } from '@servicenow/sdk-build-core'

const { resolve } = path

const loadFixture = (filepath: string) => readFileSync(resolve(__dirname, filepath), 'utf-8')

describe('SLA Plugin Tests', () => {
    const ctx = createTestContext({ rootDir: __dirname })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    describe('Validation', () => {
        test('Sla fails validation when schedule is missing', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-sla-no-schedule')

            const file = project.addFile('fixtures/validation/missing-schedule.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors).toHaveLength(1)
            expect(pluginErrors[0].message).toBe(
                'Field \'schedule\' is required when scheduleSource is "sla_definition"'
            )
        })

        test('Sla fails validation when duration is missing', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-sla-no-duration')

            const file = project.addFile('fixtures/validation/missing-duration.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors).toHaveLength(1)
            expect(pluginErrors[0].message).toBe(
                "Field 'duration' is required when durationType is empty (user specified duration)"
            )
        })

        test('Sla fails validation when both schedule and duration are missing', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-sla-no-fields')

            const file = project.addFile('fixtures/validation/missing-both-fields.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors.length).toBeGreaterThanOrEqual(1)
            const messages = pluginErrors.map((d) => d.message)
            expect(messages).toContain('Field \'schedule\' is required when scheduleSource is "sla_definition"')
        })

        test('Sla fails validation when duration is not a Duration() call', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-invalid-duration-type')

            const file = project.addFile('fixtures/validation/invalid-duration-type.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors).toHaveLength(1)
            expect(pluginErrors[0].message).toBe("SLA 'duration' field must use the Duration() helper function")
        })
    })

    describe('Round trip tests', () => {
        test('Fluent → XML → Fluent', async () => {
            const project = ctx.createProject()
            const test = new FluentXmlFluentTest(project)

            const slaId = test.addId('contract_sla', 'test-sla-roundtrip')
            test.addExpectedXmlFileNames(`contract_sla_${slaId}.xml`)
            test.addFluentFragment(loadFixture('fixtures/fluent-to-xml/basic/sla.now.ts'))

            await test.verify()
        })

        test('XML → Fluent → XML', async () => {
            const project = ctx.createProject({
                config: {
                    scope: 'x_test',
                    scopeId: '11111111111111111111111111111111',
                },
            })
            const slaId = project.registerExplicitId('contract_sla', 'test-xml-roundtrip')

            const xmlContent = loadFixture('fixtures/xml-to-fluent/basic/sla.xml').replace(
                'test-xml-roundtrip-id',
                slaId
            )

            const roundTripTest = new XmlFluentXmlTest(project, __dirname, [
                {
                    path: `contract_sla_${slaId}.xml`,
                    content: xmlContent,
                },
            ])

            await roundTripTest.verify()
        })
    })

    describe('Duration helper', () => {
        test('XML → Fluent (parses complex duration)', async () => {
            const project = ctx.createProject()
            const slaId = project.registerExplicitId('contract_sla', 'test-duration-xml')

            const xmlInput = {
                path: `contract_sla_${slaId}.xml`,
                content: loadFixture('fixtures/xml-to-fluent/duration/sla.xml').replace('test-duration-xml-id', slaId),
            }

            const { changedFiles } = await project.transform(xmlInput)
            const fluentContent = changedFiles[0]?.getContent() ?? ''

            expect(fluentContent).toContain('Duration({')
            expect(fluentContent).toContain('days: 1')
            expect(fluentContent).toContain('hours: 3')
            expect(fluentContent).toContain('minutes: 30')
        })

        test('XML → Fluent (empty duration with relative duration type)', async () => {
            const project = ctx.createProject()
            const slaId = project.registerExplicitId('contract_sla', 'test-relative-duration')

            const xmlInput = {
                path: `contract_sla_${slaId}.xml`,
                content: loadFixture('fixtures/xml-to-fluent/relative-duration/sla.xml').replace(
                    'test-relative-duration-id',
                    slaId
                ),
            }

            const { changedFiles } = await project.transform(xmlInput)
            const fluentContent = changedFiles[0]?.getContent() ?? ''

            // Duration should have fallback value of zero seconds
            expect(fluentContent).toContain('duration: Duration({')
            expect(fluentContent).toContain('seconds: 0')
            expect(fluentContent).not.toContain('undefined')
            // durationType should be in the output
            expect(fluentContent).toContain('durationType:')
        })

        test('XML → Fluent (empty string duration with relative duration type)', async () => {
            const project = ctx.createProject()
            const slaId = project.registerExplicitId('contract_sla', 'test-relative-duration-empty')

            const xmlInput = {
                path: `contract_sla_${slaId}.xml`,
                content: loadFixture('fixtures/xml-to-fluent/relative-duration/sla-empty-string.xml').replace(
                    'test-relative-duration-empty-id',
                    slaId
                ),
            }

            const { changedFiles } = await project.transform(xmlInput)
            const fluentContent = changedFiles[0]?.getContent() ?? ''

            // Duration should have fallback value of zero seconds
            expect(fluentContent).toContain('duration: Duration({')
            expect(fluentContent).toContain('seconds: 0')
            expect(fluentContent).not.toContain('undefined')
            // durationType should be in the output
            expect(fluentContent).toContain('durationType:')
        })
    })

    describe('Conditions helper', () => {
        test('Fluent → XML (converts Conditions to string)', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-conditions-fluent')

            const file = project.addFile('fixtures/fluent-to-xml/conditions/sla.now.ts')
            const xmlOutputs = await file.getOutput()

            const xmlContent = xmlOutputs[0]?.content ?? ''
            expect(xmlContent).toContain('<start_condition>priority=1</start_condition>')
            expect(xmlContent).toContain('<stop_condition>state=6</stop_condition>')
        })

        test('XML → Fluent (parses conditions as conditions object with plain strings)', async () => {
            const project = ctx.createProject()
            const slaId = project.registerExplicitId('contract_sla', 'test-conditions-xml')

            const xmlInput = {
                path: `contract_sla_${slaId}.xml`,
                content: loadFixture('fixtures/xml-to-fluent/conditions/sla.xml').replace(
                    'test-conditions-xml-id',
                    slaId
                ),
            }

            const { changedFiles } = await project.transform(xmlInput)
            const fluentContent = changedFiles[0]?.getContent() ?? ''

            expect(fluentContent).toContain('conditions: {')
            expect(fluentContent).toContain('start:')
            expect(fluentContent).toContain('priority=1')
            expect(fluentContent).toContain('state=6')
        })

        test('Fluent → XML → Fluent (round trip with Conditions)', async () => {
            const project = ctx.createProject()
            const test = new FluentXmlFluentTest(project)

            const slaId = test.addId('contract_sla', 'test-conditions-fluent')
            test.addExpectedXmlFileNames(`contract_sla_${slaId}.xml`)
            test.addFluentFragment(loadFixture('fixtures/fluent-to-xml/conditions/sla.now.ts'))

            await test.verify()
        })
    })

    describe('Duration type validations', () => {
        test('Fails when duration type is empty and duration is missing', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-sla-no-duration')

            const file = project.addFile('fixtures/validation/duration-type-empty-missing-duration.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors.length).toBeGreaterThan(0)
            expect(pluginErrors.some((e) => e.message.includes('duration'))).toBe(true)
        })

        test('Hints when duration type is relative and pause condition provided (new SLA)', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-relative-duration-pause')

            const file = project.addFile('fixtures/validation/duration-type-relative-with-pause.now.ts')

            const diagnostics = await file.getDiagnostics()
            // Level.Hint = 4
            const pluginHints = diagnostics.filter((d) => d.source === 'fluent' && d.level === 4)

            expect(pluginHints.length).toBeGreaterThan(0)
            expect(pluginHints.some((e) => e.message.includes('conditions.pause'))).toBe(true)
        })
    })

    describe('Schedule source validations', () => {
        test('Passes when schedule source is no_schedule (with forced default)', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-no-schedule-source')

            const file = project.addFile('fixtures/validation/schedule-source-no-schedule.now.ts')
            const xmlOutputs = await file.getOutput()

            const xmlContent = xmlOutputs[0]?.content ?? ''
            // Should contain the forced default schedule ID
            expect(xmlContent).toContain('<schedule>38fa64edc0a8016400f4a5724b0434b8</schedule>')
        })

        test('Fails when schedule source is task_field and scheduleSourceField is missing', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-task-field-missing')

            const file = project.addFile('fixtures/validation/schedule-source-task-field-missing-field.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors.length).toBeGreaterThan(0)
            expect(pluginErrors.some((e) => e.message.includes('scheduleSourceField'))).toBe(true)
        })

        test('Hints when schedule source is task_field and duration is provided', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-task-field-duration')

            const file = project.addFile('fixtures/validation/task-field-with-duration.now.ts')

            const diagnostics = await file.getDiagnostics()
            // Level.Hint = 4
            const pluginHints = diagnostics.filter((d) => d.source === 'fluent' && d.level === 4)
            expect(pluginHints.length).toBeGreaterThan(0)
            expect(pluginHints.some((e) => e.message.includes('duration'))).toBe(true)
        })
    })

    describe('Retroactive start validations', () => {
        test('Fails when retroactiveStart is true and setStartTo is missing', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-retroactive-no-set-start')

            const file = project.addFile('fixtures/validation/retroactive-without-set-start-to.now.ts')

            const diagnostics = await file.getDiagnostics()
            const pluginErrors = diagnostics.filter((d) => d.source === 'fluent')
            expect(pluginErrors.length).toBeGreaterThan(0)
            expect(pluginErrors.some((e) => e.message.includes('setStartTo'))).toBe(true)
        })

        test('Hints when retroactiveStart is false and setStartTo is provided', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-retroactive-false-set-start')

            const file = project.addFile('fixtures/validation/retroactive-false-with-set-start-to.now.ts')

            const diagnostics = await file.getDiagnostics()
            // Level.Hint = 4
            const pluginHints = diagnostics.filter((d) => d.source === 'fluent' && d.level === 4)
            expect(pluginHints.length).toBeGreaterThan(0)
            expect(pluginHints.some((e) => e.message.includes('setStartTo'))).toBe(true)
        })
    })

    describe('Condition field validations', () => {
        test('Hints when whenToResume is no_match and resumeCondition is provided', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-no-match-resume-condition')

            const file = project.addFile('fixtures/validation/when-to-resume-no-match-with-condition.now.ts')

            const diagnostics = await file.getDiagnostics()
            // Level.Hint = 4
            const pluginHints = diagnostics.filter((d) => d.source === 'fluent' && d.level === 4)
            expect(pluginHints.length).toBeGreaterThan(0)
            expect(pluginHints.some((e) => e.message.includes('conditions.resume'))).toBe(true)
        })

        test('Hints when whenToCancel is never and cancelCondition is provided', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-cancel-never-condition')

            const file = project.addFile('fixtures/validation/when-to-cancel-never-with-cancel-condition.now.ts')

            const diagnostics = await file.getDiagnostics()
            // Level.Hint = 4
            const pluginHints = diagnostics.filter((d) => d.source === 'fluent' && d.level === 4)
            expect(pluginHints.length).toBeGreaterThan(0)
            expect(pluginHints.some((e) => e.message.includes('conditions.cancel'))).toBe(true)
        })
    })

    describe('Timezone validations', () => {
        test('Hints when timezone is provided without timezoneSource set to sla.timezone', async () => {
            const project = ctx.createProject()
            project.registerExplicitId('contract_sla', 'test-timezone-no-source')

            const file = project.addFile('fixtures/validation/timezone-without-timezone-source.now.ts')

            const diagnostics = await file.getDiagnostics()
            // Level.Hint = 4
            const pluginHints = diagnostics.filter((d) => d.source === 'fluent' && d.level === 4)
            expect(pluginHints.length).toBeGreaterThan(0)
            expect(pluginHints.some((e) => e.message.includes('timezone'))).toBe(true)
        })
    })
})
